function storageService($window){return{set:function(key,value){return $window.localStorage[key]=value},get:function(key,defaultValue){return $window.localStorage[key]||defaultValue},setObject:function(key,value){$window.localStorage[key]=JSON.stringify(value)},getObject:function(key){return JSON.parse($window.localStorage[key]||"{}")}}}app.factory("storageService",storageService),storageService.$inject=["$window"];